import{_ as l,l as o,o as e,c as s,v as r,p as n,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"成对对逐点","description":"","frontmatter":{"title":"成对对逐点","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pairwise-vs-pointwise.md","filePath":"llm/pairwise-vs-pointwise.md","lastUpdated":1789023840000}'),c={name:"llm/pairwise-vs-pointwise.md"};function E(m,a,_,B,u,A){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="成对对逐点" tabindex="-1">成对对逐点 <a class="header-anchor" href="#成对对逐点" aria-label="Permalink to &quot;成对对逐点&quot;">​</a></h1><div class="epigraph"><p>「A 比 B 好」降低校准负担；「给 7 分」才能画趋势。两种数字回答不同的问题，不能互相换算却不声明模型。</p><footer>—— 对照 Thurstone / Bradley-Terry 的成对传统，与 Likert 绝对量表</footer></div><p><a href="/llm/llm-judge-bias">上一课</a>的偏差在成对协议里用换序处理，在逐点协议里则变成尺度漂移。本课把两种仪器分开。缺口不是再讲 Arena，而是：选成对还是逐点，先看你要排名还是要追版本。后课 Elo 默认输入已经是成对胜负。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成对：同一提示下两条回复比一次，输出胜/负/平。标注员不必把「7 分」的含义在人之间对齐，因此众包更稳，适合口味与开放生成。<a href="/llm/lmsys-arena">LMSYS Arena</a> 建立在这个选择上。代价是：没有绝对零点，不能说「这个版本 7.2 分」；新模型要和旧模型打够场次才有位置。</p><p>逐点：对单条回复打 Likert 或 rubric 分。适合看回归趋势、适合分项（事实 / 无害 / 格式）。代价是评分员漂移、尺度使用不一致、与成对胜率相关但不等于单调变换。</p><p><span class="marginnote">用逐点均值去排序模型，等于假设分数是等距的。多数 rubric 不是等距。要用成对或有序模型，不要把 1–5 当摄氏度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明「谁更好」：成对，盲，随机左右。声明「这一版是否在事实项上掉了」：同一题库上的分项逐点，固定评分员池或金标锚定。混合：先逐点筛明显失败，再对边界样本成对——与人机分工课一致。</p><p>LLM 法官同样分两套提示，不要把 MT-Bench 的比分提示改几个字当 Likert 用完就发榜。</p>',10)),(e(),n(h,null,{default:i(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20PW%5B%22%E6%88%90%E5%AF%B9%EF%BC%9A%E6%8E%92%E5%90%8D%20%2F%20%E5%8F%A3%E5%91%B3%22%5D%0A%20%20CLAIM%20--%3E%20PT%5B%22%E9%80%90%E7%82%B9%EF%BC%9A%E8%B6%8B%E5%8A%BF%20%2F%20%E5%88%86%E9%A1%B9%22%5D%0A%20%20PW%20--%3E%20BT%5B%22%E8%83%9C%E8%B4%9F%E8%BF%9B%E5%85%A5%20BT%20%2F%20Elo%22%5D%0A%20%20PT%20--%3E%20RUB%5B%22rubric%20%E5%88%86%E9%A1%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成对比较估计的是相对效用差，绝对水平被差掉。逐点估计的是与内部尺度的距离，尺度本身会走。因此「逐点平均高的模型」在成对里仍可能输：平均分被少数极高分拉起，而成对在中位提示上更常输。报告应选与决策匹配的聚合，而不是两种都算完取好看的。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>安全危害不适合纯口味成对：漏拒一条比「文风稍差」严重得多，应用分项逐点或分级严重度。下一课把成对胜负收成 Elo / Bradley-Terry 评分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成对服务排名，逐点服务趋势与分项；不可无模型换算。</li><li>Likert 非等距，禁止当连续分排序的唯一依据。</li><li>安全用严重度分级，不用口味对战。</li><li>出处：Bradley-Terry / Thurstone 传统；Arena 成对协议；rubric 人评实践。</li></ul>',6))])}const b=l(c,[["render",E]]);export{f as __pageData,b as default};
